const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to our central library and thank you for joining this morning tour.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.979208333333333},{"speaker":"A","text":"My name is Sarah and I will show you our facilities and borrowing process today.","position":2,"audioStartSeconds":5.179208333333333,"audioEndSeconds":10.270208333333333},{"speaker":"A","text":"We have three main study areas spread across the building for different needs.","position":3,"audioStartSeconds":10.470208333333334,"audioEndSeconds":15.135166666666667},{"speaker":"A","text":"The ground floor contains our large computer lab and a quiet reading room.","position":4,"audioStartSeconds":15.335166666666666,"audioEndSeconds":19.897},{"speaker":"A","text":"Students can use twenty desktop computers here without making any prior booking.","position":5,"audioStartSeconds":20.097,"audioEndSeconds":25.457833333333333},{"speaker":"A","text":"Please remember that mobile phones must remain silent inside this reading zone.","position":6,"audioStartSeconds":25.657833333333333,"audioEndSeconds":30.979208333333332},{"speaker":"A","text":"Moving up to the first floor you will find our fiction and history books.","position":7,"audioStartSeconds":31.17920833333333,"audioEndSeconds":35.664541666666665},{"speaker":"A","text":"Group study tables are also available there if you need to collaborate.","position":8,"audioStartSeconds":35.86454166666667,"audioEndSeconds":40.579875},{"speaker":"A","text":"The top floor is our dedicated silent zone for serious academic research work.","position":9,"audioStartSeconds":40.779875,"audioEndSeconds":46.25783333333333},{"speaker":"A","text":"You can borrow up to six physical books at any one time.","position":10,"audioStartSeconds":46.45783333333333,"audioEndSeconds":50.439791666666665},{"speaker":"A","text":"Standard loan periods last for three weeks before items must be renewed.","position":11,"audioStartSeconds":50.63979166666667,"audioEndSeconds":55.65266666666667},{"speaker":"A","text":"Digital textbooks and journals are accessible online through your student account password.","position":12,"audioStartSeconds":55.852666666666664,"audioEndSeconds":61.43258333333333},{"speaker":"A","text":"If you lose a library item please report the issue immediately at reception.","position":13,"audioStartSeconds":61.632583333333336,"audioEndSeconds":66.709875},{"speaker":"A","text":"Our friendly staff members are always happy to help you find resources.","position":14,"audioStartSeconds":66.909875,"audioEndSeconds":71.47175},{"speaker":"A","text":"Thank you for listening and I hope you enjoy studying in our library.","position":15,"audioStartSeconds":71.67175,"audioEndSeconds":75.83970833333333}],"questions":[{"prompt":"Number of available desktop computers: ______","answer":"twenty","evidenceSentence":5,"evidence":"twenty desktop computers","explanation":"Điền số lượng máy tính để bàn có sẵn."},{"prompt":"First floor book categories: fiction and ______","answer":"history","evidenceSentence":7,"evidence":"fiction and history books","explanation":"Điền thể loại sách ở tầng một."},{"prompt":"Top floor designation: ______ zone","answer":"silent","evidenceSentence":9,"evidence":"dedicated silent zone","explanation":"Điền tên khu vực ở tầng trên cùng."},{"prompt":"Maximum number of physical books to borrow: ______","answer":"six","evidenceSentence":10,"evidence":"up to six physical books","explanation":"Điền số lượng sách tối đa có thể mượn."},{"prompt":"Standard loan period duration: ______ weeks","answer":"three","evidenceSentence":11,"evidence":"three weeks","explanation":"Điền thời gian mượn tiêu chuẩn."},{"prompt":"Action required if losing a library item: report the issue ______","answer":"immediately","evidenceSentence":13,"evidence":"report the issue immediately","explanation":"Điền hành động khi mất sách thư viện."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
